doc.pages.filter(p=>/^Proto macOS /.test(p.name)).forEach(p=>p.layers.filter(s=>s.name.endsWith('/settings-billing--plan')).forEach(s=>{var modal=s.layers.find(l=>l.name==='Dialog');sketch.find('Text',modal).filter(t=>t.text.indexOf('Billed annually.')===0).forEach(t=>t.text='Choose monthly or annual billing. Manage or cancel in the billing portal.');modal.stackLayout.apply();modal.frame.y=(900-modal.frame.height)/2;H.out({id:s.id,modal:modal.frame});}));doc.pages.filter(p=>/^Proto macOS /.test(p.name)).forEach(p=>p.layers.filter(s=>s.name.indexOf('Screen/macos/')===0&&/settings.*--/.test(s.name)).forEach(s=>{var m=s.layers.find(l=>l.name==='Dialog');H.out({screen:s.name,modal:m.frame,screenW:s.frame.width,screenH:s.frame.height});}));H.out({colors:doc.swatches.filter(s=>/^Dark\/Clean\/(ink|secondary|surface|hover|canvas)$/.test(s.name)).map(s=>({name:s.name,color:String(s.color)}))});